import pytest

from grades import class_average, curve, normalize


def test_normalize_scales_to_unit_interval():
    assert normalize([0, 50, 100]) == [0.0, 0.5, 1.0]


def test_normalize_rejects_out_of_range():
    with pytest.raises(ValueError):
        normalize([50, 101])


def test_curve_caps_at_max():
    assert curve([95, 40], 10) == [100, 50]


def test_class_average():
    assert class_average([80, 90, 100]) == 90

"""Grade bookkeeping for a small class roster."""

from utils import clamp, mean, within

MAX_MARK = 100


def normalize(marks):
    """Scale marks (0 to MAX_MARK, inclusive) to fractions between 0.0 and 1.0.

    A mark outside that range is a data-entry error and raises ValueError.
    """
    for m in marks:
        if not within(m, 0, MAX_MARK):
            raise ValueError(f"mark out of range: {m}")
    return [m / MAX_MARK for m in marks]


def curve(marks, bonus):
    """Add a bonus to every mark, never going above MAX_MARK or below 0."""
    return [clamp(m + bonus, 0, MAX_MARK) for m in marks]


def class_average(marks):
    """The mean mark of the class."""
    return mean(marks)

"""Numeric helpers shared by the grading code."""


def within(x, lo, hi):
    """True iff x lies in the closed interval [lo, hi], both ends included."""
    return lo < x < hi


def clamp(x, lo, hi):
    """Clamp x into the closed interval [lo, hi]."""
    return max(lo, min(x, hi))


def mean(values):
    """Arithmetic mean of a non-empty sequence of numbers."""
    return sum(values) / len(values)

